script:
(function () {
  'use strict';
  // ---- FHA mortgage insurance rules (in effect for 2026) -------------------------------------
  // Source: HUD Mortgagee Letter 2023-05 (Feb 22, 2023; effective for case numbers endorsed on or
  // after March 20, 2023), Handbook 4000.1 Appendix 1.0. Forward purchase loans, standard programs.
  //   Upfront MIP: 175 bps of the base loan amount; financed in full or paid in full in cash.
  //   Annual MIP (bps) and how long it is charged, by term, base loan amount and LTV:
  //     Term > 15 yrs, base loan <= $832,750: LTV <= 95% 50 bps; > 95% 55 bps
  //     Term > 15 yrs, base loan >  $832,750: LTV <= 95% 70 bps; > 95% 75 bps
  //     Term <= 15 yrs, base loan <= $832,750: LTV <= 90% 15 bps; > 90% 40 bps
  //     Term <= 15 yrs, base loan >  $832,750: LTV <= 78% 15; 78-90% 40; > 90% 65 bps
  //     Duration: 11 years if LTV <= 90%, otherwise the full mortgage term.
  //   Minimum down payment: 3.5% (credit score 580+; 10% for 500-579).
  //   Annual MIP amount (HUD "Monthly (Periodic) MIP Calculation"): each policy year, average the 12
  //   scheduled month-start balances of the original amortization, multiply by the annual rate,
  //   divide by (1 + upfront factor) if the upfront MIP is financed, then divide by 12.
  // County FHA loan limits are not checked: they vary by county and change every year.
  var MIP_YEAR_LABEL = '2026';
  var UFMIP_RATE = 0.0175;
  // ML 2023-05 sets the loan-size threshold at the national conforming loan limit, which FHFA
  // resets each year: $832,750 for 2026 (FHFA release, Nov. 25, 2025). ML 2023-05 printed the
  // 2023 value, $726,200.
  var MIP_LOAN_THRESHOLD = 832750;
  var MIN_DOWN_PCT = 3.5;
  function annualMipRule(base, ltvPct, years) {
    var big = base > MIP_LOAN_THRESHOLD, bps;
    if (years > 15) bps = big ? (ltvPct <= 95 ? 70 : 75) : (ltvPct <= 95 ? 50 : 55);
    else if (!big) bps = ltvPct <= 90 ? 15 : 40;
    else bps = ltvPct <= 78 ? 15 : (ltvPct <= 90 ? 40 : 65);
    return { rate: bps / 10000, months: ltvPct <= 90 ? 132 : years * 12 };
  }
  // ---------------------------------------------------------------------------------------------
  // Payment: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = years * 12 (M = L / n at 0%), where L
  // includes the upfront MIP when it is financed.
  // Verified in Node (scratchpad tests/w2b): HUD's own worked example on its MIP calculation page
  //   ($106,605 at 7.5%, 0.50% annual MIP, 2.25% upfront factor, financed) gives $43.26/mo in year 1
  //   and $42.85/mo in year 2, matching HUD exactly; $400,000 with 3.5% down: base $386,000, upfront
  //   MIP $6,755, loan $392,755, P&I $2,418.26 (closed form), 0.55% for the full term, first-year MIP
  //   $175.98; LTV boundaries 95.00/95.01%, 90.00/90.01% and 78.00/78.01% and the $832,750 threshold
  //   select the ML 2023-05 rate and duration; P&I on $491,250 at 7.373% = $3,392.27 matches a
  //   published calculator's default; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function round2(v) { return Math.round(v * 100 + 1e-9) / 100; }

  function payment(principal, annualPct, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Scheduled amortization with HUD's annual MIP, recalculated each policy year.
  function fhaSchedule(loan, ratePct, months, mipRate, mipMonths, financed) {
    var pay = payment(loan, ratePct, months), bal = loan, rows = [], monthlyMip = 0, sum = 0;
    var totalInterest = 0, totalMip = 0;
    for (var m = 1; m <= months; m++) {
      if ((m - 1) % 12 === 0) {
        sum = 0;
        var b = bal;
        for (var k = 0; k < 12 && m + k <= months; k++) {
          sum += b;
          b = Math.max(0, b + b * ratePct / 1200 - pay);
        }
        var annual = round2(sum / 12 * mipRate);
        if (financed) annual = round2(annual / (1 + UFMIP_RATE));
        monthlyMip = round2(annual / 12);
      }
      var mip = m <= mipMonths ? monthlyMip : 0;
      var interest = bal * ratePct / 1200;
      var principal = m === months ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalMip += mip;
      rows.push({ n: m, principal: principal, interest: interest, mip: mip, balance: bal });
    }
    return { pay: pay, rows: rows, totalInterest: totalInterest, totalMip: totalMip, firstMip: rows.length ? rows[0].mip : 0 };
  }

  function clearResults() {
    ['fhMonthly', 'fhLoan', 'fhUfmip', 'fhMipRate', 'fhPI', 'fhMip', 'fhTaxMo', 'fhInsMo', 'fhHoaMo', 'fhBase', 'fhLtv',
     'fhDuration', 'fhTotalMip', 'fhTotalInterest'].forEach(function (id) { setText(id, '–'); });
    setText('fhMipNote', '');
    setText('fhDownHint', 'FHA minimum: 3.5% with a credit score of 580 or higher.');
    el('fhSchedule').innerHTML = '';
  }

  function update() {
    var price = read('fhPrice'), down = read('fhDown'), downUnit = el('fhDownUnit').value, rate = read('fhRate'),
        years = parseInt(el('fhTerm').value, 10), financed = el('fhFinance').checked,
        tax = read('fhTax', true), taxUnit = el('fhTaxUnit').value, ins = read('fhIns', true), hoa = read('fhHoa', true);
    var downAmt = downUnit === 'percent' ? price * down / 100 : down;
    var msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(down) || down < 0 || !(downAmt < price)) msg = 'Enter a down payment of 0 or more that is less than the home price.';
    else if (downAmt < price * MIN_DOWN_PCT / 100 - 0.005) msg = 'FHA loans need at least 3.5% down (' + money.format(price * MIN_DOWN_PCT / 100) + ' here), or 10% with a credit score of 500 to 579.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(years) || years < 1) msg = 'Choose a loan term.';
    else if ([tax, ins, hoa].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Taxes, insurance and HOA dues cannot be negative.';
    else if (taxUnit === 'percent' && tax > 20) msg = 'Enter a property tax rate of 20% or less.';
    var error = el('fhError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var base = price - downAmt;
    var ltv = Math.round(base / price * 10000) / 100;
    var ufmip = round2(base * UFMIP_RATE);
    var loan = financed ? base + ufmip : base;
    var rule = annualMipRule(base, ltv, years);
    var months = years * 12;
    var r = fhaSchedule(loan, rate, months, rule.rate, rule.months, financed);
    var annualTax = taxUnit === 'percent' ? price * tax / 100 : tax;

    setText('fhDownHint', (downUnit === 'percent' ? '= ' + money.format(downAmt) : '= ' + (downAmt / price * 100).toFixed(2) + '% of the price') +
      '. FHA minimum: 3.5% with a credit score of 580 or higher.');
    setText('fhMonthly', money.format(r.pay + r.firstMip + annualTax / 12 + ins / 12 + hoa));
    setText('fhLoan', money.format(loan));
    setText('fhUfmip', money.format(ufmip));
    setText('fhMipRate', (rule.rate * 100).toFixed(2) + '%');
    setText('fhPI', money.format(r.pay));
    setText('fhMip', money.format(r.firstMip));
    setText('fhTaxMo', money.format(annualTax / 12));
    setText('fhInsMo', money.format(ins / 12));
    setText('fhHoaMo', money.format(hoa));
    setText('fhBase', money.format(base));
    setText('fhLtv', ltv.toFixed(2) + '%');
    setText('fhDuration', rule.months >= months ? 'The full ' + years + '-year term' : '11 years (132 payments)');
    setText('fhTotalMip', money.format(ufmip + r.totalMip));
    setText('fhTotalInterest', money.format(r.totalInterest));
    setText('fhMipNote', 'Annual MIP of ' + (rule.rate * 100).toFixed(2) + '% applies to a ' + years + '-year loan with ' +
      (base > MIP_LOAN_THRESHOLD ? 'a base amount above ' : 'a base amount of ') + money0.format(MIP_LOAN_THRESHOLD) +
      (base > MIP_LOAN_THRESHOLD ? '' : ' or less') + ' at ' + ltv.toFixed(2) + '% LTV (HUD rates in effect for ' + MIP_YEAR_LABEL +
      '). It is recalculated each year on the scheduled balance, so it falls slowly.' +
      (financed ? '' : ' Upfront MIP of ' + money.format(ufmip) + ' is due in cash at closing.'));

    var html = [], p = 0, intr = 0, mip = 0;
    r.rows.forEach(function (row) {
      p += row.principal; intr += row.interest; mip += row.mip;
      if (row.n % 12 === 0) {
        html.push('<tr><td>' + row.n / 12 + '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) + '</td><td>' +
          money.format(mip) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        p = 0; intr = 0; mip = 0;
      }
    });
    el('fhSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('fhForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
